// @ts-nocheck
import React, { useState, useEffect } from 'react';
import {
  List,
  ActionPanel,
  Action,
  getSelectedText,
  Clipboard,
  showHUD,
  popToRoot,
  Icon,
  Color,
} from '@raycast/api';
import { Tone, RewriteChoice } from './types';
import { fetchOllamaRewrites } from './engine/ollama';

const RList: any = List;
const RActionPanel: any = ActionPanel;
const RAction: any = Action;

export default function Command() {
  const [selectedText, setSelectedText] = useState<string>('');
  const [activeTone, setActiveTone] = useState<Tone>('professional');
  const [choices, setChoices] = useState<RewriteChoice[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    async function loadText() {
      try {
        const text = await getSelectedText();
        if (text && text.trim().length > 0) {
          setSelectedText(text.trim());
          const results = await fetchOllamaRewrites(text.trim(), activeTone);
          setChoices(results);
        } else {
          setSelectedText('Select text in any app before opening Spelling Launcher.');
        }
      } catch {
        const clipboardText = await Clipboard.readText();
        if (clipboardText && clipboardText.trim().length > 0) {
          setSelectedText(clipboardText.trim());
          const results = await fetchOllamaRewrites(clipboardText.trim(), activeTone);
          setChoices(results);
        } else {
          setSelectedText('Highlight text in any text box or document to rewrite.');
        }
      } finally {
        setIsLoading(false);
      }
    }

    loadText();
  }, [activeTone]);

  const handlePaste = async (text: string) => {
    await Clipboard.paste(text);
    await showHUD('🚀 Rewritten and pasted!');
    await popToRoot();
  };

  const tones: { id: Tone; label: string; icon: Icon }[] = [
    { id: 'professional', label: 'Professional', icon: Icon.Document },
    { id: 'casual', label: 'Casual', icon: Icon.Message },
    { id: 'academic', label: 'Academic', icon: Icon.Book },
    { id: 'confident', label: 'Confident', icon: Icon.CheckCircle },
    { id: 'shorten', label: 'Shorten', icon: Icon.MinusCircle },
    { id: 'expand', label: 'Expand', icon: Icon.PlusCircle },
  ];

  return (
    <RList
      isLoading={isLoading}
      isShowingDetail
      searchBarPlaceholder="Filter variations or choose tone..."
      searchBarAccessory={
        <RList.Dropdown
          tooltip="Select Rewrite Tone"
          value={activeTone}
          onChange={(val: any) => {
            setIsLoading(true);
            setActiveTone(val as Tone);
          }}
        >
          {tones.map((t) => (
            <RList.Dropdown.Item key={t.id} title={t.label} value={t.id} icon={t.icon} />
          ))}
        </RList.Dropdown>
      }
    >
      <RList.Section title={`Ollama Rewrites for: "${selectedText.slice(0, 40)}..."`}>
        {choices.map((choice) => (
          <RList.Item
            key={choice.id}
            title={choice.rewrittenText}
            subtitle={choice.label}
            icon={{ source: Icon.Rocket, tintColor: Color.Green }}
            detail={<RList.Item.Detail markdown={choice.diffMarkdown} />}
            actions={
              <RActionPanel>
                <RAction
                  title="Paste into Active App"
                  icon={Icon.Check}
                  onAction={() => handlePaste(choice.rewrittenText)}
                />
                <RAction.CopyToClipboard
                  title="Copy to Clipboard"
                  content={choice.rewrittenText}
                />
                <RActionPanel.Submenu title="Change Tone" icon={Icon.Switch}>
                  {tones.map((t) => (
                    <RAction
                      key={t.id}
                      title={t.label}
                      icon={t.icon}
                      onAction={() => {
                        setIsLoading(true);
                        setActiveTone(t.id);
                      }}
                    />
                  ))}
                </RActionPanel.Submenu>
              </RActionPanel>
            }
          />
        ))}
      </RList.Section>
    </RList>
  );
}
